const safe = (value) => /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(value) ? value : JSON.stringify(value);
export function printApprovalChain(chain, appRefName) {
    const imports = ["approvalProcess", ...(chain.stageId !== undefined ? ["unsafeApprovalStageId"] : [])];
    const lines = [`import { ${imports.join(", ")} } from "@elementumai/edk/approvalProcesses";`, `import catalog from "@catalog";`];
    const props = [
        `app: catalog.${safe(appRefName)}`,
        `name: ${JSON.stringify(chain.name)}`,
        ...(chain.stage !== undefined ? [`stage: ${JSON.stringify(chain.stage)}`] : []),
        ...(chain.stageId !== undefined ? [`unsafeStageId: unsafeApprovalStageId(${JSON.stringify(chain.stageId)})`] : []),
        `numberOfDynamicApprovers: ${chain.numberOfDynamicApprovers}`,
        `managedByAutomation: ${chain.managedByAutomation}`,
        `denyButton: ${JSON.stringify(chain.denyButton)}`,
        `approveButton: ${JSON.stringify(chain.approveButton)}`,
        ...(chain.exceptionButton !== undefined ? [`exceptionButton: ${JSON.stringify(chain.exceptionButton)}`] : []),
        ...(chain.defaultReason !== undefined ? [`defaultReason: ${JSON.stringify(chain.defaultReason)}`] : []),
        ...(chain.summary !== undefined ? [`summary: ${JSON.stringify(chain.summary)}`] : []),
        ...(chain.lockedFields.length > 0 ? [`lockedFields: [${[...chain.lockedFields].sort().map((key) => `catalog.${safe(appRefName)}.fields.${safe(key)}`).join(", ")}]`] : []),
    ];
    lines.push(``, `export default approvalProcess({`, ...props.map((prop) => `  ${prop},`), `});`, ``);
    return lines.join("\n");
}
